<?php use App\Support\App;App::requireAdmin();$db=App::db();$keys=$db->query('SELECT COUNT(*) FROM api_keys WHERE is_active=1')->fetchColumn();$logs=$db->query('SELECT a.*,u.email FROM api_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.id DESC LIMIT 200')->fetchAll();$title='API & Logs';require __DIR__.'/../layouts/head.php';require __DIR__.'/../components/app_start.php';?><div><h1 class="page-title">API & Logs</h1><p class="page-sub">Aktivitas Open API dan credential pengguna.</p></div><div class="grid sm:grid-cols-2 gap-3 mt-6"><div class="saas-card metric"><span class="metric-label">Active API keys</span><div class="metric-value"><?=$keys?></div></div><div class="saas-card metric"><span class="metric-label">Recent API requests</span><div class="metric-value"><?=count($logs)?></div></div></div><div class="saas-card mt-5 overflow-auto"><table class="w-full text-sm min-w-[750px]"><thead><tr><th>User</th><th>Method</th><th>Endpoint</th><th>Status</th><th>IP</th><th>Date</th></tr></thead><tbody><?php foreach($logs as $r):?><tr class="border-t" style="border-color:var(--line)"><td><?=htmlspecialchars($r['email']??'-')?></td><td><span class="badge"><?=htmlspecialchars($r['method'])?></span></td><td><code><?=htmlspecialchars($r['endpoint'])?></code></td><td><?=htmlspecialchars($r['status_code'])?></td><td><?=htmlspecialchars($r['ip'])?></td><td><?=htmlspecialchars($r['created_at'])?></td></tr><?php endforeach?></tbody></table></div><?php require __DIR__.'/../components/app_end.php';require __DIR__.'/../layouts/foot.php';?>